update public.stat_categories c set title=case when d.p ? 'title' then d.p->>'title' else c.title end,plain_language_description=case when d.p ? 'plain_language_description' then d.p->>'plain_language_description' else c.plain_language_description end,value_type=case when d.p ? 'value_type' then d.p->>'value_type' else c.value_type end,measurement_type=case when d.p ? 'measurement_type' then d.p->>'measurement_type' else c.measurement_type end,metadata=c.metadata||coalesce(d.p->'metadata','{}'::jsonb) from definition_restoration d where c.id=d.p->>'id';
